<?php use App\Core\Csrf; use App\Helpers\ViewHelper; ?><div class="auth-page container"><form class="form-card" method="post" action="/login"><p class="eyebrow">Tài khoản</p><h1>Đăng nhập</h1><?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?><?= Csrf::field() ?><label for="email">Email</label><input id="email" name="email" type="email" value="<?= ViewHelper::escape($email ?? '') ?>" required><label for="password">Mật khẩu</label><input id="password" name="password" type="password" required><button class="button button-primary" type="submit">Đăng nhập</button><a class="button google-login-button" href="/auth/google">Tiếp tục với Google</a><p><a href="/forgot-password">Quên mật khẩu?</a></p><p>Chưa có tài khoản? <a href="/register">Đăng ký</a></p></form><form class="form-card verification-resend-form" method="post" action="/verify-email/resend"><h2>Chưa nhận được email xác thực?</h2><?= Csrf::field() ?><label for="verification-email">Email đăng ký</label><input id="verification-email" name="verification_email" type="email" required><button class="button" type="submit">Gửi lại email xác thực</button></form></div>
